using System;using UnityEngine;using LWS.TruckSports;
namespace LWS.TruckMusicalParking.Editor {public static class ParkingFixtures {public static void Run(){int n=0;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("Parking fixture: "+label);n++;};var g=new GameObject("Temporary footprint fixture");try{var body=g.AddComponent<Rigidbody>();body.isKinematic=true;var box=g.AddComponent<BoxCollider>();box.size=new Vector3(1.5f,1,3);check(ParkingRules.Contains(box,body,Vector3.zero,Quaternion.identity,new Vector2(4.8f,7.5f)),"whole centered body fits");body.position=Vector3.right*1.9f;check(!ParkingRules.Contains(box,body,Vector3.zero,Quaternion.identity,new Vector2(4.8f,7.5f)),"center alone cannot claim partial footprint");body.position=Vector3.zero;body.rotation=Quaternion.Euler(0,45,0);check(ParkingRules.Contains(box,body,Vector3.zero,Quaternion.identity,new Vector2(4.8f,7.5f)),"actual angled footprint valid when fully inside");body.position=Vector3.right*1.5f;check(!ParkingRules.Contains(box,body,Vector3.zero,Quaternion.identity,new Vector2(4.8f,7.5f)),"angled protruding chassis rejected");}finally{UnityEngine.Object.DestroyImmediate(g);}check(ParkingRules.BetterClaim(1,7,2,0,0),"earliest stable claim wins");check(ParkingRules.BetterClaim(1,4,1,1,3)&&!ParkingRules.BetterClaim(1,1,1,4,3),"true simultaneous claims use rotated priority");var active=new bool[8];var secured=new int[8];var progress=new float[8];var distance=new float[8];for(int i=0;i<8;i++){active[i]=true;secured[i]=i<6?i:-1;distance[i]=3;}progress[6]=.2f;progress[7]=.4f;check(ParkingRules.Lowest(active,secured,progress,distance,0)==6,"lowest current valid progress loses");progress[6]=progress[7]=0;distance[7]=7;check(ParkingRules.Lowest(active,secured,progress,distance,0)==7,"equal progress loses by greater free-space distance");distance[7]=3;check(ParkingRules.Lowest(active,secured,progress,distance,7)==7,"exact timeout tie uses rotating priority");active[7]=false;check(ParkingRules.Lowest(active,secured,progress,distance,7)==6,"exactly one active unparked contender selected");Debug.Log("PARKING_RULE_FIXTURES_PASS count="+n);}}}
